  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some(column => column.name === 'due_date')) {
  db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}

const page = await readFile(new URL('./index.html', import.meta.url));

function sendJson(res, status, data) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readJson(req) {
  let body = '';
  for await (const chunk of req) body += chunk;
  return JSON.parse(body);
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') {
    return sendJson(res, 200, { status: 'ok' });
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
    return sendJson(res, 200, db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completed_count,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS total_count
      FROM projects p WHERE p.archived = ? ORDER BY p.id`).all(archived));
  }
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return sendJson(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (req.method === 'GET' && projectMatch) {
    const project = db.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? sendJson(res, 200, project) : sendJson(res, 404, { error: 'Project not found' });
  }
  const projectPriorityMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/default-priority$/);
  if (req.method === 'PATCH' && projectPriorityMatch) {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    if (!['Low', 'Normal', 'High'].includes(data.priority)) return sendJson(res, 400, { error: 'Invalid task priority' });
    const id = Number(projectPriorityMatch[1]);
    const project = db.prepare('SELECT archived FROM projects WHERE id = ?').get(id);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(res, 409, { error: 'Archived project' });
    db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(data.priority, id);
    return sendJson(res, 200, { ok: true });
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (req.method === 'POST' && renameMatch) {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return sendJson(res, 400, { error: 'Project name is required' });
    const result = db.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0').run(name, Number(renameMatch[1]));
    if (!result.changes) {
      const project = db.prepare('SELECT id, archived FROM projects WHERE id = ?').get(Number(renameMatch[1]));
      if (!project) return sendJson(res, 404, { error: 'Project not found' });
      return sendJson(res, 409, { error: 'Archived project' });
    }
    return sendJson(res, 200, { name });
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (req.method === 'POST' && archiveMatch) {
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    return result.changes ? sendJson(res, 200, { ok: true }) : sendJson(res, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    const project = db.prepare('SELECT id, archived, default_priority FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') {
      return sendJson(res, 200, db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id').all(projectId));
    }
    if (req.method === 'POST') {
      if (project.archived) return sendJson(res, 409, { error: 'Archived project' });
      let data;
      try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
      const title = typeof data.title === 'string' ? data.title.trim() : '';
      if (!title) return sendJson(res, 400, { error: 'Task title is required' });
      const result = db.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)').run(projectId, title, project.default_priority);
      return sendJson(res, 201, { id: Number(result.lastInsertRowid), title, completed: 0, priority: project.default_priority });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  const taskRenameMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/rename$/);
  const taskDueDateMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/due-date$/);
  if (req.method === 'POST' && taskDueDateMatch) {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const rawDate = typeof data.due_date === 'string' ? data.due_date.trim() : '';
    let dueDate = null;
    if (rawDate) {
      const match = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (!match) return sendJson(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
      const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
      const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
      const monthDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      if (year < 1 || month < 1 || month > 12 || day < 1 || day > monthDays[month - 1]) {
        return sendJson(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
      }
      dueDate = rawDate;
    }
    const taskId = Number(taskDueDateMatch[1]);
    const task = db.prepare('SELECT t.id, p.archived FROM tasks t JOIN projects p ON p.id = t.project_id WHERE t.id = ?').get(taskId);
    if (!task) return sendJson(res, 404, { error: 'Task not found' });
    if (task.archived) return sendJson(res, 409, { error: 'Archived project' });
    db.prepare('UPDATE tasks SET due_date = ? WHERE id = ?').run(dueDate, taskId);
    return sendJson(res, 200, { due_date: dueDate });
  }
  if (req.method === 'POST' && taskRenameMatch) {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const title = typeof data.title === 'string' ? data.title.trim() : '';
    if (!title) return sendJson(res, 400, { error: 'Task title is required' });
    const taskId = Number(taskRenameMatch[1]);
    const task = db.prepare('SELECT t.id, p.archived FROM tasks t JOIN projects p ON p.id = t.project_id WHERE t.id = ?').get(taskId);
    if (!task) return sendJson(res, 404, { error: 'Task not found' });
    if (task.archived) return sendJson(res, 409, { error: 'Archived project' });
    db.prepare('UPDATE tasks SET title = ? WHERE id = ?').run(title, taskId);
    return sendJson(res, 200, { title });
  }
  if (req.method === 'PATCH' && taskMatch) {
    let data;
    try { data = await readJson(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const hasCompletion = Object.hasOwn(data, 'completed');
    const hasPriority = Object.hasOwn(data, 'priority');
    if (!hasCompletion && !hasPriority) return sendJson(res, 400, { error: 'No task changes supplied' });
    if (hasCompletion && typeof data.completed !== 'boolean') return sendJson(res, 400, { error: 'Invalid completion state' });
    if (hasPriority && !['Low', 'Normal', 'High'].includes(data.priority)) return sendJson(res, 400, { error: 'Invalid task priority' });
    const taskId = Number(taskMatch[1]);
    const task = db.prepare('SELECT t.id, p.archived FROM tasks t JOIN projects p ON p.id = t.project_id WHERE t.id = ?').get(taskId);
    if (!task) return sendJson(res, 404, { error: 'Task not found' });
    if (task.archived) return sendJson(res, 409, { error: 'Archived project' });
    if (hasCompletion && hasPriority) {
      db.prepare('UPDATE tasks SET completed = ?, priority = ? WHERE id = ?').run(data.completed ? 1 : 0, data.priority, taskId);
    } else if (hasCompletion) {
      db.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(data.completed ? 1 : 0, taskId);
    } else {
      db.prepare('UPDATE tasks SET priority = ? WHERE id = ?').run(data.priority, taskId);
    }
    const result = { changes: 1 };
    return result.changes ? sendJson(res, 200, { ok: true }) : sendJson(res, 404, { error: 'Task not found' });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return res.end(page);
  }
  sendJson(res, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
